package io.lumine.mythic.lib.api.util.ui;
public class PlusMinusPercent {
 double constant; boolean relative,multiply; public PlusMinusPercent(double c,boolean add,boolean mul){constant=c;relative=add;multiply=mul;} public double apply(double base){double v=constant;if(multiply){if(relative)v+=1;return base*v;}return relative?base+v:v;} public double reverse(double base){double v=constant;if(multiply){if(relative)v+=1;return base/v;}return relative?base-v:base;} public void setConstant(double c){constant=c;} public void setAdditive(boolean v){relative=v;} public void setMultiplicative(boolean v){multiply=v;} public double getConstant(){return constant;} public boolean isAdditive(){return relative;} public boolean isMultiplicative(){return multiply;}
 public static PlusMinusPercent getFromString(String input){return getFromString(input,null);} public static PlusMinusPercent getFromString(String input,FriendlyFeedbackProvider f){if(input==null||input.isBlank())return null;String s=input.trim();boolean mul=s.endsWith("%");if(mul)s=s.substring(0,s.length()-1);boolean add=s.startsWith("+")||s.startsWith("-");boolean negN=s.startsWith("n")||s.startsWith("N");double sign=1;if(s.startsWith("+"))s=s.substring(1);else if(s.startsWith("-")){sign=-1;s=s.substring(1);}else if(negN){sign=-1;s=s.substring(1);}try{double v=Double.parseDouble(s)*sign;if(mul)v/=100d;return new PlusMinusPercent(v,add,mul);}catch(NumberFormatException e){FriendlyFeedbackProvider.log(f,FriendlyFeedbackCategory.ERROR,"Cant parse numeric value from '$r{0}$b'.",s);return null;}}
 @Override public String toString(){double v=constant;StringBuilder b=new StringBuilder();if(relative&&!multiply)b.append(v<0?'-':'+');else if(v<0)b.append('n');v=Math.abs(v)*(multiply?100d:1d);String n=String.format(java.util.Locale.ROOT,"%.2f",v).replaceAll("0+$","").replaceAll("\\.$","");return b.append(n).append(multiply?'%':"").toString();}
}
